<?php

namespace App\Support;

/**
 * Indonesian administrative regions (province → city/regency → district) shipped as static JSON in
 * public/data/wilayah, generated by scripts/build_wilayah.py. The address form reads the same files.
 */
class Wilayah
{
    private static ?array $tree = null;

    /**
     * Whether the district belongs to the city and the city to the province, matched by name.
     */
    public static function isValid(?string $provinsi, ?string $kota, ?string $kecamatan): bool
    {
        $province = collect(self::tree())->firstWhere('nama', $provinsi);
        $city = $province ? collect($province['kota'])->firstWhere('nama', $kota) : null;
        if (!$city) {
            return false;
        }

        $file = public_path('data/wilayah/kecamatan/' . $city['kode'] . '.json');

        return is_file($file) && in_array($kecamatan, json_decode(file_get_contents($file), true) ?? [], true);
    }

    private static function tree(): array
    {
        return self::$tree ??= json_decode(file_get_contents(public_path('data/wilayah/provinsi-kota.json')), true) ?? [];
    }
}
